 // middle[ 3]  ==  0x13  ==  0x13  ==  middle[131075]
 // middle[ 4]  ==  0x30  ==  0x30  ==  middle[131076]
 // middle[ 5]  ==  0x31  ==  0x31  ==  middle[131077]
