           wuffs_base__store_u8__no_bounds_check(&buf[0x0006], lp);
           wuffs_base__store_u8__no_bounds_check(&buf[0x0007], ln);
           wuffs_base__store_u32be__no_bounds_check(&buf[0x8], vmajor);
