     if (status.repr == NULL) {
       return NULL;
     } else if (status.repr == wuffs_base__suspension__short_read) {
       TRY(read_src());
     } else if (status.repr == wuffs_base__suspension__short_write) {
       wuffs_base__token_buffer__compact(&tok);
     } else {
       return wuffs_base__status__message(&status);
     }
   }
