 		while.goto_parsed_a_leaf_value true {
 			if args.dst.available() <= 0 {
 				yield? base."$short write"
 				continue.outer
 			}

 			// Consume whitespace.
 			whitespace_length = 0
 			c = 0
 			class = 0
