 						value_minor: 0,
 						link: 0x0,
 						length: 0xFFFF)
 					whitespace_length = 0
 					continue.outer
 				}
 				whitespace_length += 1
 			} endwhile.ws

 			// Emit whitespace.
 			if whitespace_length > 0 {
 				args.dst.write_fast_token!(
 					value_major: 0,
 					value_minor: 0,
 					link: 0x0,
 					length: whitespace_length)
 				whitespace_length = 0
 				if args.dst.available() <= 0 {
