 								continue.string_loop_outer
 							}
 							string_length += 4
 						}

 						c = args.src.peek_u8()
 						char = lut_chars[c]

 						if char == 0x00 {  // Non-special ASCII.
 							args.src.skip32_fast!(actual: 1, worst_case: 1)
 							if string_length >= 0xFFFB {
 								args.dst.write_fast_token!(
 									value_major: 0,
 									value_minor: 0x40_0021,
 									link: 0x3,
 									length: 0xFFFC)
 								string_length = 0
 								continue.string_loop_outer
 							}
 							string_length += 1
 							continue.string_loop_inner

