 							if string_length <> 0 {
 								args.dst.write_fast_token!(
 									value_major: 0,
 									value_minor: 0x40_0021,
 									link: 0x3,
 									length: string_length)
 								string_length = 0
 							}
 							break.string_loop_outer

 						} else if char == 0x02 {  // '\\'.
 							if string_length > 0 {
 								args.dst.write_fast_token!(
 									value_major: 0,
 									value_minor: 0x40_0021,
 									link: 0x3,
 									length: string_length)
 								string_length = 0
 								if args.dst.available() <= 0 {
 									continue.string_loop_outer
 								}
