 							backslash = lut_backslashes[c]
 							if (backslash & 0x80) <> 0 {
 								args.src.skip32_fast!(actual: 2, worst_case: 2)
 								args.dst.write_fast_token!(
 									value_major: 0,
 									value_minor: 0x60_0000 | ((backslash & 0x7F) as base.u32),
 									link: 0x3,
 									length: 2)
 								continue.string_loop_outer

 							} else if backslash <> 0 {
