fuzz(wuffs_base__io_buffer* src, uint64_t hash) {
  const char* s0 = fuzz_swizzle_interleaved_from_slice(src, hash);
  const char* s1 = fuzz_swizzle_ycck(src, hash);
  if (s0 && strstr(s0, "internal error:")) {
